import {
  Component,
  ComponentInterface,
  Element,
  Prop,
  State,
  Event,
  h,
  EventEmitter,
  Host,
  Listen,
  Watch,
} from '@stencil/core';
import { isNil, isObject } from 'lodash-es';
import {
  computePosition,
  Placement,
  autoUpdate,
  flip,
  shift,
  offset,
  arrow,
  Strategy,
  hide,
  type ReferenceElement,
  platform,
  Middleware,
  limitShift,
} from '@floating-ui/dom';
import { offsetParent } from 'composed-offset-position';
import { Slot, Slots, Uncontrollable } from '@src/framework/decorators';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { cancellableDelayedTask } from './utils/cancellable-delayed-task';
import { PopoverTrigger, TooltipSize } from './types';
import {
  allocateFallbackZIndex,
  CSSProperties,
  isEventFromTopLayerSurface,
  KS_TOP_LAYER_SURFACE_ATTR,
  supportsPopoverApi,
} from '@src/shared/dom';
import { cancelElementAnimations, createOpenCloseMotion } from '@src/shared/animation';
import { observeClickOutside } from './utils/observe-click-outside';
import { sendDurationTracking, sendExposeTracking } from '@src/shared/unclassified/tracking';

const prefix = 'tooltip';
const DEFAULT_TRIGGER = 'hover';
const DEFAULT_PLACEMENT = 'top';
const topLayerSurfaceAttrs = { [KS_TOP_LAYER_SURFACE_ATTR]: '' };

const slotRangeCache = new WeakMap<HTMLSlotElement, Range | HTMLElement | undefined>();

const DEFAULT_DELAY: {
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  [K in PopoverTrigger]: number;
} = {
  hover: 200,
  focus: 100,
  click: 0,
  manual: 0,
};

const getSizeMaxWidth = (size: TooltipSize): string | undefined => {
  switch (size) {
    case 'auto':
      return '100vw';
    case 'sm':
      return '240px';
    case 'md':
      return '320px';
    case 'lg':
      return '480px';
    default:
      return undefined;
  }
};

export type PopupLength = string | number | 'matchAnchor';
const _containsMatchAnchorLength = (
  lengthConfig?: PopupLength | { min?: PopupLength; value?: PopupLength; max?: PopupLength },
) =>
  typeof lengthConfig === 'object'
    ? Object.values(lengthConfig).some((v) => v === 'matchAnchor')
    : lengthConfig === 'matchAnchor';

/**
 * @slot default - The trigger or anchor content that reveals the tooltip when users interact with it.
 * @slot content - Slot for the main content to be displayed inside the tooltip. This is an alternative to using the `content` prop.
 * @part arrow - The popup arrow that points to the trigger element.
 * @part content - The content container.
 */
@Component({
  tag: 'ks-tooltip',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsTooltip implements ComponentInterface {
  static vModel = { prop: 'open', event: 'ksOpenChange' };
  @Element() el!: HTMLKsTooltipElement;

  /** Controls the visibility of the popup. When `true`, the popup is open. */
  @Prop() open?: boolean;
  /** The default visibility of the popup when the component is first rendered. */
  @Prop() defaultOpen = false;
  @Uncontrollable('open', 'defaultOpen', 'ksOpenChange') @State() mergedOpen?: boolean;
  /** Disables the tooltip trigger and keeps the popup closed. */
  @Prop() disabled = false;
  /** The content displayed inside the popup. */
  @Prop() content?: string;
  /** The placement of the popup relative to the target element. */
  @Prop() placement: Placement = DEFAULT_PLACEMENT;
  /** The trigger method for showing the popup. Can be one of the following values: `click`, `hover`, `focus` or `manual`. */
  @Prop() trigger: PopoverTrigger = DEFAULT_TRIGGER;
  /** Delay before the popup can get open/close, in milliseconds. */
  @Prop() delay?: { open?: number; close?: number };
  /** The background color of the popup. */
  @Prop() color?: string;
  /** The font color of the text inside the popup. */
  @Prop() fontColor?: string;
  /** Indicates whether to inverse the popup. When `true`, the popup will have a highlighted appearance. */
  @Prop() inverse = false;
  /** Controls whether outside clicks close the tooltip, or provides elements to ignore during outside-click detection. */
  @Prop() closeOnClickOutside: boolean | { ignoreEls: HTMLElement[] } = true;
  /** Controls whether the tooltip displays an arrow pointing to the trigger element. */
  @Prop() arrow?: boolean = true;
  /** The positioning strategy for the popup. Can be either `"absolute"` or `"fixed"`. */
  @Prop() strategy: Strategy = 'fixed';
  /** The offset between the popup and the target element. */
  @Prop() gapOffset = 0;
  /** The offset for positioning the popup at the start. */
  @Prop() startOffset = 0;
  /** The size of the popup. Can be one of the following values: `"auto"`, `"sm"`, `"md"`, `"lg"`. */
  @Prop() size: TooltipSize = 'auto';
  /** The duration of the transition in milliseconds. */
  @Prop() transitionDuration = 200;
  /** The anchor element to which the popup is attached. This can be an element outside the tooltip children. */
  @Prop() anchorEl?: HTMLElement | (() => HTMLElement);
  /** Controls whether the tooltip can shift, flip, or hide when the anchor leaves the viewport. */
  @Prop() autoAdjustments?: { shift?: boolean; flip?: boolean; hideOnAnchorExit?: boolean } = {
    shift: true,
    flip: true,
    hideOnAnchorExit: true,
  };
  /** Overrides the width of the popup decided by `size`. */
  @Prop() popupWidth?: PopupLength | { min?: PopupLength; value?: PopupLength; max?: PopupLength };
  /** Overrides the height of the popup decided by `size`. */
  @Prop() popupHeight?: PopupLength | { min?: PopupLength; value?: PopupLength; max?: PopupLength };
  /** Indicates whether to remove the default padding for the popup content. */
  @Prop() noPadding = false;
  /** The style of the popup content. */
  @Prop() partProps?: { content?: { style?: CSSProperties } };
  /** Overrides the z-index value of the popup. */
  @Prop() zIndex?: string | number;
  /** The word break property of the popup content. */
  @Prop() wordBreak: CSSStyleDeclaration['wordBreak'] = 'normal';
  /** The white space property of the popup content. */
  @Prop() whiteSpace: CSSStyleDeclaration['whiteSpace'] = 'normal';
  /** Triggers after the popup has opened. */
  @Prop() afterOpen?: () => void;
  /** Triggers after the popup has closed. */
  @Prop() afterClose?: () => void;
  /** Triggers when the visibility of the popup changes. */
  @Event({ bubbles: false, composed: false }) ksOpenChange!: EventEmitter<boolean>;

  @Listen('ksOpenChange')
  onKsOpenChange(event: CustomEvent<boolean>) {
    if (event.target !== this.el) {
      return;
    }

    const open = event.detail;
    if (open) {
      sendExposeTracking(this.el, { eventType: 'popup' });
      sendDurationTracking(this.el, { eventType: 'popup', reset: true });
    } else {
      sendDurationTracking(this.el, { eventType: 'popup' });
    }
  }

  /** The slot for the popup content. */
  @Slot({ slotname: 'content' }) private contentSlot?: Slots;

  private anchorSlotRef?: HTMLSlotElement;
  private popupRef?: HTMLElement;
  private arrowRef?: HTMLDivElement;

  @State() anchorWidth?: number;
  @State() anchorHeight?: number;

  constructor() {
    registerPluginManager(this.el);
  }

  @State() isVisible = false;
  @State() fallbackZIndex?: string;
  private openChangeAnimation = createOpenCloseMotion();

  private get shouldControlTopLayerWithPopoverApi() {
    return this.shouldUseTopLayer && supportsPopoverApi(this.popupRef);
  }

  private get shouldRenderPopup() {
    return this.isVisible && !this.disabled && Boolean(this.content || this.contentSlot?.length);
  }

  @Watch('mergedOpen')
  handleOpenChange(newValue: boolean) {
    const popup = this.popupRef;
    if (!popup) {
      return;
    }

    const completeClose = () => {
      popup.removeAttribute('ks-open');
      popup.style.visibility = 'hidden';
      if (this.shouldControlTopLayerWithPopoverApi) {
        if (popup.isConnected) {
          try {
            popup.hidePopover();
          } catch (e) {
            // ignore InvalidStateError if the popover is already hidden
          }
        }
      }
      this.isVisible = Boolean(this.mergedOpen);
      this.syncFallbackZIndex();
      this.afterClose?.();
    };

    if (newValue) {
      this.isVisible = true;
      this.syncFallbackZIndex();

      if (this.shouldControlTopLayerWithPopoverApi) {
        if (popup.isConnected) {
          try {
            popup.showPopover();
          } catch (e) {
            // ignore InvalidStateError if the popover is already shown
          }
        }
      }
      popup.setAttribute('ks-open', '');
      popup.style.visibility = this.shouldRenderPopup ? 'visible' : 'hidden';
    }

    this.openChangeAnimation.fade(popup, newValue, {
      duration: this.transitionDuration,
      checkConnected: false,
      afterOpen: () => this.afterOpen?.(),
      afterClose: completeClose,
    });
  }

  private handleInitialOpen() {
    this.isVisible = Boolean(this.mergedOpen);
    if (this.popupRef) {
      if (this.shouldControlTopLayerWithPopoverApi) {
        try {
          this.isVisible ? this.popupRef.showPopover() : this.popupRef.hidePopover();
        } catch (e) {
          // ignore InvalidStateError when the initial popover state is already applied
        }
      }
      if (this.isVisible) {
        this.popupRef.setAttribute('ks-open', '');
      } else {
        this.popupRef.removeAttribute('ks-open');
      }
      this.popupRef.style.opacity = this.isVisible ? '1' : '0';
      this.popupRef.style.visibility = this.shouldRenderPopup ? 'visible' : 'hidden';
      if (this.isVisible) {
        this.afterOpen?.();
      }
    }
  }

  private get shouldUseTopLayer() {
    return !this.zIndex && this.zIndex !== 0;
  }

  private syncFallbackZIndex() {
    if (this.shouldControlTopLayerWithPopoverApi) {
      this.fallbackZIndex = undefined;
      return;
    }

    if (this.zIndex || this.zIndex === 0) {
      this.fallbackZIndex = String(this.zIndex);
      return;
    }

    if (this.isVisible) {
      this.fallbackZIndex = allocateFallbackZIndex();
    }
  }

  private resolveSlotContent(slotEl: HTMLSlotElement): Range | HTMLElement | undefined {
    if (slotRangeCache.has(slotEl)) {
      return slotRangeCache.get(slotEl);
    }

    let range: Range | HTMLElement | undefined;
    const assignedNode = slotEl.assignedNodes({ flatten: true });
    if (assignedNode[0]) {
      if (assignedNode.length === 1 && assignedNode[0] instanceof HTMLElement) {
        return assignedNode[0];
      }

      range = document.createRange();
      range.setStartBefore(assignedNode[0]);
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
      range.setEndAfter(assignedNode[assignedNode.length - 1]!);
    }

    if (range) {
      slotRangeCache.set(slotEl, range);
    }
    return range;
  }
  private removeSlotRangeCache = () => {
    this.anchorSlotRef && slotRangeCache.delete(this.anchorSlotRef);
    this.listenTrigger();
    this.autoUpdatePopup();
  };

  /** This may not be a real element, but a range for position calculation by floating-ui only. */
  private get anchorCalculationReference(): ReferenceElement | undefined {
    let anchorEl: HTMLElement | Range | undefined =
      typeof this.anchorEl === 'function' ? this.anchorEl() : this.anchorEl;
    anchorEl ||= this.anchorSlotRef && this.resolveSlotContent(this.anchorSlotRef);

    return anchorEl;
  }

  // eslint-disable-next-line max-lines-per-function
  private updatePopupPosition = async () => {
    const popup = this.popupRef;
    if (!this.isVisible || !this.anchorCalculationReference || !popup) {
      this.anchorWidth = undefined;
      this.anchorHeight = undefined;
      return;
    }

    const middleware: Array<Middleware | null | undefined | false> = [
      offset({
        mainAxis: (this.arrow ? 10 : 4) + this.gapOffset,
        crossAxis: this.startOffset,
      }),
      this.autoAdjustments?.hideOnAnchorExit !== false && hide(),
      {
        name: 'anchorRects',
        fn: ({ rects }) => ({ data: rects.reference }),
      },
    ];
    const flipMiddleware = this.autoAdjustments?.flip !== false && flip();
    const shiftMiddleware = this.autoAdjustments?.shift !== false && shift({ padding: 8, limiter: limitShift() });
    const targetPlacement = this.placement || DEFAULT_PLACEMENT;
    if (targetPlacement.includes('-')) {
      middleware.push(flipMiddleware, shiftMiddleware);
    } else {
      middleware.push(shiftMiddleware, flipMiddleware);
    }

    if (this.arrowRef) {
      middleware.push(arrow({ element: this.arrowRef, padding: 12 }));
    }

    const state = await computePosition(this.anchorCalculationReference, popup, {
      middleware,
      placement: targetPlacement,
      strategy: this.strategy,
      platform: {
        ...platform,
        getOffsetParent: (element) => platform.getOffsetParent(element, offsetParent),
      },
    });

    const { x, y, placement, middlewareData } = state;
    popup.setAttribute('data-popper-placement', placement);
    Object.assign(popup.style, {
      position: this.strategy,
      left: 0,
      top: 0,
      transform: `translate3d(${x}px, ${y}px, 0)`,
      visibility: middlewareData.hide?.referenceHidden || !this.shouldRenderPopup ? 'hidden' : '',
    });

    if (this.arrowRef && middlewareData.arrow) {
      let { x: arrowX, y: arrowY } = middlewareData.arrow;

      // Fix for *-start and *-end placements with large reference elements:
      // By default, Floating UI points the arrow to the center of the reference.
      // If the reference is very large, the arrow might be clamped to the far end of the popup,
      // which contradicts the user's expectation of the arrow being near the start/end edge.
      const arrowPadding = 16;
      const shiftX = middlewareData.shift?.x || 0;
      const shiftY = middlewareData.shift?.y || 0;

      if (placement.endsWith('-start')) {
        if (placement.startsWith('right') || placement.startsWith('left')) {
          if (!isNil(arrowY) && shiftY === 0) {
            arrowY = Math.min(arrowY, arrowPadding);
          }
        } else {
          if (!isNil(arrowX) && shiftX === 0) {
            arrowX = Math.min(arrowX, arrowPadding);
          }
        }
      } else if (placement.endsWith('-end')) {
        if (placement.startsWith('right') || placement.startsWith('left')) {
          if (!isNil(arrowY) && shiftY === 0) {
            const max = popup.offsetHeight - this.arrowRef.offsetHeight - arrowPadding;
            arrowY = Math.max(arrowY, max);
          }
        } else {
          if (!isNil(arrowX) && shiftX === 0) {
            const max = popup.offsetWidth - this.arrowRef.offsetWidth - arrowPadding;
            arrowX = Math.max(arrowX, max);
          }
        }
      }

      Object.assign(this.arrowRef.style, {
        left: isNil(arrowX) ? '' : `${arrowX}px`,
        top: isNil(arrowY) ? '' : `${arrowY}px`,
      });
    }

    if (_containsMatchAnchorLength(this.popupWidth)) {
      this.anchorWidth = middlewareData['anchorRects'].width;
    }
    if (_containsMatchAnchorLength(this.popupHeight)) {
      this.anchorHeight = middlewareData['anchorRects'].height;
    }
  };

  private _updatePopupBy: ReferenceElement | undefined;
  private _cleanupAutoUpdate?: () => void;
  private autoUpdatePopup() {
    const popup = this.popupRef;
    const updatePopupBy = this.isVisible && popup ? this.anchorCalculationReference : undefined;
    if (updatePopupBy !== this._updatePopupBy) {
      this._updatePopupBy = updatePopupBy;
      this._cleanupAutoUpdate?.();
      this._cleanupAutoUpdate = undefined;
      if (updatePopupBy && popup) {
        this._cleanupAutoUpdate = autoUpdate(updatePopupBy, popup, this.updatePopupPosition);
      }
    }
  }

  private _cleanupDelayedAction?: ReturnType<typeof cancellableDelayedTask>;
  private triggerOpenChange(newOpen: boolean, trigger: PopoverTrigger) {
    this._cleanupDelayedAction?.();

    const delay = newOpen
      ? (this.delay?.open ?? DEFAULT_DELAY[trigger])
      : (this.delay?.close ?? DEFAULT_DELAY[trigger]);
    this._cleanupDelayedAction = cancellableDelayedTask(() => (this.mergedOpen = newOpen), delay || 0);
  }

  private _listenedAnchor: Element | undefined;
  private _listenedTrigger: PopoverTrigger | undefined;
  private _listenedObserveOutsideClick?: boolean;
  private _listenedIgnoredOutsideEls?: HTMLElement[];
  private _triggerListenerCleanups: (() => void)[] = [];
  private get anchorEventTarget(): Element | undefined {
    const externalAnchorEl = typeof this.anchorEl === 'function' ? this.anchorEl() : this.anchorEl;
    if (externalAnchorEl) {
      return externalAnchorEl;
    }

    return this.anchorSlotRef?.assignedElements({ flatten: true })[0] || this.anchorSlotRef;
  }
  private _cleanupTriggerListeners() {
    while (this._triggerListenerCleanups.length) {
      this._triggerListenerCleanups.pop()?.();
    }
    this._listenedAnchor = undefined;
    this._listenedTrigger = undefined;
    this._listenedObserveOutsideClick = undefined;
    this._listenedIgnoredOutsideEls = undefined;
  }
  private _listenEvent(target: EventTarget, eventName: string, handler: EventListener) {
    target.addEventListener(eventName, handler);
    this._triggerListenerCleanups.push(() => target.removeEventListener(eventName, handler));
  }
  private listenTrigger() {
    const popup = this.popupRef;
    let triggerToListen: PopoverTrigger | undefined = this.trigger;
    if (this.disabled || !popup) {
      triggerToListen = undefined;
    }

    const anchorToListen = this.anchorEventTarget;
    const observeOutsideClick = triggerToListen === 'click' && this.closeOnClickOutside !== false;
    const ignoredOutsideEls =
      typeof this.closeOnClickOutside === 'object' && Array.isArray(this.closeOnClickOutside.ignoreEls)
        ? this.closeOnClickOutside.ignoreEls
        : undefined;

    if (
      this._listenedTrigger !== triggerToListen ||
      this._listenedAnchor !== anchorToListen ||
      this._listenedObserveOutsideClick !== observeOutsideClick ||
      this._listenedIgnoredOutsideEls !== ignoredOutsideEls
    ) {
      this._cleanupTriggerListeners();
      this._listenedTrigger = triggerToListen;
      this._listenedAnchor = anchorToListen;
      this._listenedObserveOutsideClick = observeOutsideClick;
      this._listenedIgnoredOutsideEls = ignoredOutsideEls;

      if (!anchorToListen || !popup) {
        return;
      }
      const anchorAndPopup = [anchorToListen, popup];

      anchorAndPopup.forEach((target) => {
        if (triggerToListen === 'hover') {
          this._listenEvent(target, 'pointerenter', () => this.triggerOpenChange(true, 'hover'));
          this._listenEvent(target, 'pointerleave', () => this.triggerOpenChange(false, 'hover'));
        } else if (triggerToListen === 'focus') {
          this._listenEvent(target, 'focusin', () => this.triggerOpenChange(true, 'focus'));
          this._listenEvent(target, 'focusout', () => this.triggerOpenChange(false, 'focus'));
        }
      });

      if (triggerToListen === 'click') {
        this._listenEvent(anchorToListen, 'click', (e: Event) => {
          // [Workaround-START]
          // FIXME click events bubble up across nested popups: top-layer popup content keeps its
          // real DOM position, so a click inside a popup nested within this anchor bubbles up here.
          // See [issue#1] in KsOverlay. Skip it so it doesn't toggle this tooltip.
          if (isEventFromTopLayerSurface(e, e.currentTarget)) {
            return;
          }
          // [Workaround-END]
          this.triggerOpenChange(!this.mergedOpen, 'click');
        });
        if (observeOutsideClick) {
          this._triggerListenerCleanups.push(
            observeClickOutside([...anchorAndPopup, ...(ignoredOutsideEls || [])], () =>
              this.triggerOpenChange(false, 'click'),
            ),
          );
        }
      }
    }
  }

  private _resolveMatchAnchorLength(type: 'width' | 'height', length: PopupLength | undefined): string | undefined {
    const resolvedLength =
      length === 'matchAnchor' ? (type === 'width' ? this.anchorWidth : this.anchorHeight) : length;
    if (typeof resolvedLength === 'number') {
      return `${resolvedLength}px`;
    }
    return isNil(resolvedLength) ? resolvedLength : String(resolvedLength);
  }
  private resolvePopupLengthStyle(
    type: 'width' | 'height',
    lengthConfig?: PopupLength | { min?: PopupLength; value?: PopupLength; max?: PopupLength },
  ) {
    if (isNil(lengthConfig)) {
      return {};
    } else if (isObject(lengthConfig)) {
      const val = this._resolveMatchAnchorLength(type, lengthConfig.value);
      const min = this._resolveMatchAnchorLength(type, lengthConfig.min);
      const max = this._resolveMatchAnchorLength(type, lengthConfig.max);

      let resolvedMax = !isNil(max) ? max : val;
      if (resolvedMax === 'auto') {
        resolvedMax = 'none';
      }

      return {
        [type]: val,
        [type === 'width' ? 'minWidth' : 'minHeight']: min,
        [type === 'width' ? 'maxWidth' : 'maxHeight']: resolvedMax,
      };
    } else {
      const resolved = this._resolveMatchAnchorLength(type, lengthConfig);
      return {
        [type]: resolved,
        [type === 'width' ? 'maxWidth' : 'maxHeight']: resolved === 'auto' ? 'none' : resolved,
      };
    }
  }
  private resolvePopupWidthStyle(): CSSProperties {
    // size acts as the default max-width baseline; popupWidth (when explicit) overrides it.
    const widthStyle = this.resolvePopupLengthStyle('width', this.popupWidth);
    return {
      ...widthStyle,
      maxWidth: widthStyle['maxWidth'] ?? getSizeMaxWidth(this.size),
    };
  }

  connectedCallback() {
    this.listenTrigger();
    this.autoUpdatePopup();
  }
  componentDidRender() {
    this.listenTrigger();
    this.autoUpdatePopup();
  }
  componentWillLoad() {
    this.isVisible = Boolean(this.mergedOpen);
    this.syncFallbackZIndex();
  }
  componentDidLoad() {
    this.handleInitialOpen();
  }
  disconnectedCallback() {
    const popup = this.popupRef;
    this.openChangeAnimation.dispose();
    this._cleanupTriggerListeners();
    this._cleanupAutoUpdate?.();
    this._cleanupDelayedAction?.();

    if (popup) {
      popup.removeAttribute('ks-open');
      cancelElementAnimations(popup);
    }
  }

  render() {
    return (
      <Host class="KsTooltip">
        <div
          {...topLayerSurfaceAttrs}
          ref={(el) => (this.popupRef = el)}
          class={{
            [prefix]: true,
            [`${prefix}__popup`]: true,
            [`${prefix}__popup--inverse`]: this.inverse,
          }}
          style={{
            color: this.inverse || !this.fontColor ? undefined : `${this.fontColor}`,
            // TODO optimize the performance here by filter the content slot in compatibility layer
            visibility: this.shouldRenderPopup ? '' : 'hidden',
            pointerEvents: this.isVisible ? undefined : 'none',
            zIndex: this.fallbackZIndex,
            ...this.resolvePopupWidthStyle(),
            ...this.resolvePopupLengthStyle('height', this.popupHeight),
          }}
          popover={this.shouldUseTopLayer ? 'manual' : undefined}
        >
          {this.arrow && (
            <div ref={(el) => (this.arrowRef = el)} part="arrow" class={`${prefix}__popup-arrow`}>
              <span style={{ color: this.color }}></span>
            </div>
          )}
          <div
            class={{
              [`${prefix}__popup-content`]: true,
              [`${prefix}__popup-content--no-padding`]: this.noPadding,
            }}
            part="content"
            style={{
              wordBreak: this.wordBreak,
              whiteSpace: this.whiteSpace,
              backgroundColor: this.inverse ? undefined : this.color,
              ...(this.partProps?.content?.style || {}),
            }}
          >
            <slot name="content">{this.content}</slot>
          </div>
        </div>

        <slot
          onSlotchange={this.removeSlotRangeCache}
          ref={(el) => (this.anchorSlotRef = el as HTMLSlotElement | undefined)}
        ></slot>
      </Host>
    );
  }
}
