interface Observation {
  containEls: Element[];
  callback: () => void;
}

const _observations = new Set<Observation>();
const _elementToObservationsMap = new WeakMap<Element, Set<Observation>>();
let _listeningDocument: Document | undefined;

const _clickOutsideHandler = (event: MouseEvent) => {
  if (!_observations.size) {
    return;
  }

  const insidePathObservations = new Set<Observation>();
  for (const el of event.composedPath()) {
    if ((el as Node).nodeType === 1) {
      _elementToObservationsMap.get(el as Element)?.forEach((obs) => insidePathObservations.add(obs));
    }
  }

  _observations.forEach((observation) => {
    if (!insidePathObservations.has(observation)) {
      // Use microtask to ensure the callback happens after click event handler directly set on element called
      Promise.resolve().then(() => observation.callback());
    }
  });
};

const _ensureClickOutsideHandler = () => {
  if (_listeningDocument === document) {
    return;
  }
  _listeningDocument?.removeEventListener('click', _clickOutsideHandler, true);
  document.addEventListener('click', _clickOutsideHandler, { capture: true, passive: true });
  _listeningDocument = document;
};

/** @returns The cleanup function for the observation. */
export function observeClickOutside(containEls: Element | Element[], callback: () => void): () => void {
  containEls = Array.isArray(containEls) ? containEls : [containEls];

  if (!containEls.length) {
    return () => {
      /* noop */
    };
  }

  const observation: Observation = { containEls, callback };
  _ensureClickOutsideHandler();
  _observations.add(observation);

  for (const el of containEls) {
    let observationsOfElement = _elementToObservationsMap.get(el);
    if (!observationsOfElement) {
      observationsOfElement = new Set();
      _elementToObservationsMap.set(el, observationsOfElement);
    }
    observationsOfElement.add(observation);
  }

  return () => {
    _observations.delete(observation);

    for (const el of containEls) {
      const observationsOfElement = _elementToObservationsMap.get(el);
      if (observationsOfElement) {
        observationsOfElement.delete(observation);
        if (observationsOfElement.size === 0) {
          _elementToObservationsMap.delete(el);
        }
      }
    }
  };
}
